-- This script upserts deterministic records and does not delete manual rows.

begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "098abe03-b9b8-558f-940f-c95440815567", "feature_slug": "currency", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Basic Currency Config | `/merchant-currency-settings/basic` | `bff_get_basic_currency_config()`, `bff_upsert_basic_currency_config()` |\n| Currency Settings | `/merchant-currency-settings` | `bff_get_currency_config()`, `bff_upsert_currency_config()` |\n| Earn Studio (advanced) | `/earn-studio` | `bff_get_earn_studio_config()`, `bff_upsert_earn_studio()` |\n\n### 4a. Configure Basic Earn Rate\n\n1. Open **Basic Currency Config** — select target currency (points or ticket type)\n2. Toggle \"Different rate per tier\" — off for a single rate, on for per-tier rates\n3. If single rate: enter the spend amount per 1 currency unit (e.g., 30 = spend 30 THB for 1 point)\n4. If per-tier: a row appears for each tier — enter rate per tier (lower number = better rate for that tier)\n5. Optionally add excluded products via pill selector (SKU, product, brand, or category)\n6. Click **Save** — toast confirms success\n\n### 4b. Add Multipliers\n\n1. On **Basic Currency Config**, scroll to the Multipliers section\n2. Toggle \"Allow Stacking\" to control whether multipliers combine\n3. Click **\"+ Add Multiplier\"** to create a multiplier card\n4. Configure: multiplier rate, active toggle, window dates, timing (weekend/weekday/custom), eligible tiers, and included products\n5. Repeat for additional multipliers — each appears as a separate card\n6. Delete a multiplier via the trash icon on its card\n7. Click **Save** — backend handles creation, update, and deletion of factors automatically\n\n### 4c. Configure Expiry and Award Timing\n\n1. Open **Currency Settings** — two sections: Points Expiry and Currency Award Timing\n2. Points Expiry: enable checkbox, select mode (TTL, fixed frequency), configure mode-specific fields\n3. Award Timing: select delay type (immediate, delayed by days/minutes, or scheduled time), configure accordingly\n4. Click **Save** — COALESCE-based upsert safely merges with existing config\n\n### 4d. Advanced Earn Rules (Earn Studio)\n\n1. Open **Earn Studio** — displays all earn factor groups in a sidebar\n2. Select a group to view its factors and conditions in the main panel\n3. Configure factor-level settings: type (rate/multiplier), target currency, conditions, thresholds, operators\n4. This page handles complex scenarios that exceed basic mode: multi-entity conditions, threshold rules, personalized offers, and shared condition groups\n5. If basic mode detects configuration too complex for its UI, it redirects to Earn Studio with a `mode: \"not_basic\"` indicator", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/currency.md#L90 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "bb876cde8a08d48bbdbff47d5695dfd832f9c4792f371a564d1a03a832a11b78", "truncated": false}, "is_active": true}, {"id": "4c0e844e-cb64-5e85-adc3-fadb27f6297f", "feature_slug": "currency", "title": "Business Rules Summary", "content": "### Core Principles\n1. **No Double-Counting**: Each baht of spending earns currency exactly once\n2. **Customer-Favorable Selection**: When multiple earning rules qualify, customer gets the best rate (\"best rate wins\")\n3. **Inheritance Hierarchy**:\n   - Explicit factor settings override group settings\n   - NULL values inherit from group\n   - System defaults apply when both are NULL\n4. **Currency Combination**:\n   - Public and private offers evaluate together\n   - One rate per currency type (best rate selected)\n   - Multiple multipliers follow stacking rules per group\n5. **Scope Isolation**: Product-specific and transaction-wide multipliers can coexist even in non-stackable groups\n   - Product multipliers consume their portion of the transaction amount\n   - Transaction multipliers apply only to the unconsumed remainder\n   - Prevents double-multiplying while allowing dual incentives\n   - Enables simultaneous product promotions and customer recognition\n6. **Unified Source Processing**:\n   - All sources (purchase, referral, mission, campaign, manual) use same pipeline\n   - `calc_currency_for_source` routes to appropriate calculation\n   - Single observability layer via `inngest_workflow_log`\n7. **Durable Execution Guarantees**:\n   - Inngest persists workflow state across restarts\n   - **Inngest workflow state IS the pending state** - no database pending table needed\n   - Step-level retries (3 attempts per step)\n   - Workflows cancelled via `currency/cancelled` event with `cancelOn` matching (`source_type + source_id`)\n   - Delayed awards survive system restarts\n8. **Processing Guarantees**:\n   - Four-level idempotency: Kafka offset, Redis dedup, Inngest event ID, Database constraint\n   - Exactly-once award processing\n   - Atomic wallet updates with row-level locking\n   - Complete audit trail in `wallet_ledger` and `inngest_workflow_log`\n9. **Precise Cancellation**:\n   - Refund cancels only the specific source''s pending award (not all user awards)\n   - `cancelOn` matches `source_type + source_id` for precision\n   - No database lookup needed for cancellation\n9. **Fungible vs Non-fungible Separation**:\n   - Points transactions always have `target_entity_id = NULL`\n   - Ticket transactions always have `target_entity_id = ticket_type.id`\n   - Each ticket type tracked independently with separate balances\n   - Unique constraint includes `currency` for multi-currency support\n10. **Currency Expiry Rules**:\n    - Expiry dates are immutable once set (no retroactive changes)\n    - Only unused currency expires (deductible balance protection)\n    - Expiry calculation must be atomic with currency award\n    - Failed expiry calculation prevents currency award (data integrity)\n    - Points expiry applies uniformly to all users per merchant\n    - Ticket expiry can vary by ticket type\n    - Minimum period protection overrides fiscal period boundaries\n\n### Edge Cases and Handling\n\n**Zero-Value Transactions**:\n- Transactions with 0 THB amount earn 0 currency\n- System still creates ledger entry for audit\n\n**Partial Refunds**:\n- Currency reversed proportionally to refund amount\n- Original multipliers considered in reversal calculation\n\n**Tier Changes Mid-Transaction**:\n- Tier at transaction start time is used\n- Prevents gaming through rapid tier changes\n\n**Expired Personalized Offers**:\n- Checked at calculation time, not assignment time\n- Graceful fallback to public offers\n\n### Performance Targets\n- Calculation response: Under 100ms for 95% of requests\n- System throughput: 1,200+ transactions per second\n- Availability: 99.9% uptime\n- Queue processing latency: < 5 minutes average\n- Materialized view staleness: < 15 minutes maximum\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Currency.md#L1847 Business Rules Summary", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a2c961eed7197bf006d8d096fc99564f61ba019f87901e13584e28ef8fa5883e", "truncated": false}, "is_active": true}, {"id": "a59601ab-cf30-548b-a2cf-cc4c3096f1f1", "feature_slug": "currency", "title": "(1) Currency Calculation Engine", "content": "### Overview\nThe calculation engine determines how much currency (points and tickets) a customer should earn from their purchase. It evaluates all applicable earning rules, applies business logic, and returns the calculated amounts without modifying any balances.\n\n### System Architecture Diagram\n\n```mermaid\ngraph TB\n    subgraph \"Data Sources (CDC Monitored)\"\n        PL[purchase_ledger]\n        RL[referral_ledger]\n        MC[mission_claims]\n    end\n    \n    subgraph \"Change Data Capture\"\n        PL & RL & MC --> Debezium[Confluent CDC Connector]\n        Debezium --> Kafka[Kafka Topics]\n    end\n    \n    subgraph \"Render Consumer - crm-event-processors\"\n        Kafka --> Consumer[Currency Consumer]\n        Consumer --> Redis[Redis Dedup Check<br/>per source_type + source_id]\n        Redis --> CALC[calc_currency_for_source RPC]\n        CALC --> Timing[Calculate Award Time]\n        Timing --> Publish[Publish currency/award to Inngest]\n    end\n    \n    subgraph \"Durable Execution - Inngest\"\n        Publish --> INN[Inngest Cloud]\n        INN --> EF2[inngest-currency-serve<br/>Edge Function]\n        EF2 --> WF1[currency-award workflow]\n        EF2 --> WF2[currency-reversal workflow]\n    end\n    \n    subgraph \"Calculation Engine\"\n        CALC --> CE2[calc_currency_for_transaction]\n        CE2 --> CE3[get_eligible_earn_factors]\n        CE3 --> MV[Materialized Views]\n    end\n    \n    subgraph \"Configuration Cache\"\n        Consumer --> CFG[getMerchantCurrencyConfig]\n        CFG --> REDIS2[Upstash Redis<br/>Merchant Config Cache]\n        REDIS2 -.->|cache miss| MM[merchant_master table]\n    end\n    \n    subgraph \"Wallet Layer\"\n        WF1 --> POST[post_wallet_transaction]\n        WF2 --> POST\n        POST --> WL[wallet_ledger]\n        POST --> UW[user_wallet / user_ticket_balances]\n    end\n    \n    subgraph \"Observability\"\n        WF1 & WF2 --> LOG[inngest_workflow_log]\n    end\n    \n    subgraph \"Cancellation Flow\"\n        Consumer -->|Refund detected| CancelEvent[Publish currency/cancelled]\n        CancelEvent --> INN\n        INN -->|cancelOn triggers| WF1\n    end\n```\n\n> **Architecture Note (v2.0)**: Currency now uses CDC → Render Consumer → Inngest pattern, matching Tier architecture. No pending table needed - Inngest workflow state IS the pending state.\n\n### Calculation Process\n\n#### Step 1: Gather Applicable Earning Rules\nThe system identifies all earning rules that could apply to this transaction:\n\n**Public Earning Rules Query**:\n- Find all factors where public = true\n- Check merchant matches\n- Verify currently within window period (considering inheritance)\n- Confirm active status (considering inheritance)\n\n**Personalized Offers Query**:\n- Look up customer''s assigned offers in earn_factor_user table\n- Verify assignments haven''t expired\n- Get factor details from earn_factor table\n- Apply same window and active status checks\n\nBoth sets combine into a single pool of candidates for evaluation.\n\n**Performance Note**: The system uses the `get_eligible_earn_factors()` function which leverages materialized views for sub-50ms response times.\n\n#### Step 2: Check Qualifying Conditions\nEach earning rule may have conditions that must be met, stored in the earn_conditions table:\n\n**Condition Types**:\n- Product Conditions: Specific SKUs, brands, or categories (with optional quantity/amount thresholds)\n- Customer Conditions: Tier level requirements\n- Store Conditions: Store attribute set requirements\n- Combined Conditions: Must meet ALL conditions in a group\n\n**Threshold Configuration** (v2.1 Feature):\nProduct conditions can include minimum and maximum thresholds measured in three ways:\n\n1. **`quantity_primary`**: Check primary quantity field (standard units)\n   - Examples: bags, pieces, bottles, boxes, sachets\n   - Defined in `product_sku_master.uom_primary`\n   - Measured in `purchase_items_ledger.quantity`\n   - Use case: \"Buy ≥50 bags of cement → 5x points\"\n\n2. **`quantity_secondary`**: Check secondary quantity field (bulk units)\n   - Examples: tonnes, pallets, cartons, cases, trays\n   - Defined in `product_sku_master.uom_secondary`\n   - Measured in `purchase_items_ledger.quantity_secondary`\n   - Use case: \"Buy ≥2 tonnes of steel → 10x points\"\n\n3. **`amount`**: Check line total value in currency\n   - Measured in `purchase_items_ledger.line_total`\n   - Use case: \"Spend ≥5000 THB on electronics → 3x points\"\n\n**Threshold Fields** (in `earn_conditions` table):\n- **`threshold_unit`** (TEXT): Which measurement to check\n  - Values: `quantity_primary`, `quantity_secondary`, `amount`, or `NULL` (no threshold)\n- **`min_threshold`** (NUMERIC): Minimum value required to qualify\n  - If not met, earn factor does not apply\n- **`max_threshold`** (NUMERIC): Maximum eligible value (cap)\n  - Prevents abuse on very large purchases\n  - Example: \"Max 1000 units\" caps bonus even if customer buys 5000\n- **`apply_to_excess_only`** (BOOLEAN): Multiplier application mode\n  - `false` (default): **Full Line Mode** - Multiplier applies to entire matched line value\n  - `true`: **Excess Only Mode** - Multiplier applies only to quantity/value above minimum threshold\n\n**Multiplier Application Modes**:\n\n*Full Line Mode* (`apply_to_excess_only = false`):\n```\nCustomer buys 60 bags (min threshold: 50)\n→ 5x multiplier applies to ALL 60 bags\n```\n\n*Excess Only Mode* (`apply_to_excess_only = true`):\n```\nCustomer buys 60 bags (min threshold: 50)\n→ 5x multiplier applies ONLY to 10 bags (60 - 50 = 10 excess)\n```\n\n**Scope Determination**:\n- Rules with product conditions → Apply only to matching items\n- Rules with only tier conditions → Apply to entire transaction\n- Rules with no conditions → Apply to entire transaction\n- Rules with thresholds → Must meet minimum to activate, capped at maximum if specified\n\n**Product Exclusions** (`exclude = true` on `earn_condition`):\n\nExclusion conditions allow specific products, SKUs, brands, or categories to be removed from an otherwise eligible set. The evaluation engine uses a two-pass approach:\n\n*Pass 1 — Include conditions (`exclude = false`):*\n- Product include conditions: build the eligible item set from matching items\n- If no include product conditions exist: base = all items in the transaction\n- Tier / persona / store conditions: transaction-wide gates, unchanged\n\n*Pass 2 — Exclude conditions (`exclude = true`, product entities only):*\n- Find item_ids matching any exclude condition\n- Remove them from the eligible item set built in Pass 1\n- If eligible set becomes empty after exclusion → factor does not apply\n\n**Exclusion examples**:\n```\nEarn on everything except gift cards:\n  conditions_group:\n    → earn_condition: entity=product_sku, entity_ids=[gift_card_sku_id], exclude=true\n\nEarn on Shoes collection, except sale items:\n  conditions_group:\n    → earn_condition: entity=product_category, entity_ids=[shoes_cat_id], exclude=false  (include)\n    → earn_condition: entity=product_sku, entity_ids=[sale_sku_1, sale_sku_2], exclude=true  (exclude)\n```\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Currency.md#L578 (1) Currency Calculation Engine", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4ac8b7ece0c9e9c9a53b17c33804f1c703fb4658811d3eeaba76509bb31a914e", "truncated": true}, "is_active": true}, {"id": "fb65c7b2-03cb-580b-ab20-f4831e50ea08", "feature_slug": "currency", "title": "7. Business Rules", "content": "**Rule:** Only one rate factor per currency type applies per transaction. When multiple rates qualify, the best rate (lowest spend-per-unit) wins.\n**Example:** Rates of 100 THB/pt and 50 THB/pt both qualify → member gets the 50 THB rate (more points per baht).\n\n**Rule:** Product-specific and transaction-wide multipliers can coexist in non-stackable groups because they operate on mutually exclusive portions of the transaction amount.\n**Example:** Shoes (300 THB) at 3x + birthday 5x on remainder (700 THB) = 9 + 35 = 44 points. No amount is multiplied twice.\n\n**Rule:** Reversals use historical calculation data preserved in `wallet_ledger.metadata` — never current earn factors.\n**Example:** Member earned 500 points during a 5x New Year promo. Promo ended. 50% refund reverses 250 points (not 50, which current 1x rate would yield).\n\n**Rule:** Expiry dates are immutable once set. Only the deductible balance (original minus redemptions) expires.\n**Example:** Member earned 100 points (expiry Jul 15), redeemed 60. On Jul 15, only 40 points expire.\n\n**Rule:** Minimum period protection overrides fiscal period boundaries.\n**Example:** Points earned Nov 1 with quarterly expiry and 6-month minimum → expires May, not Dec 31.\n\n**Rule:** Factor settings inherit from parent group unless explicitly overridden. NULL values at factor level fall through to group values.\n**Example:** Group window is Apr 1 – Jun 30. Factor with no window dates inherits Apr 1 – Jun 30. Factor with explicit dates uses its own.\n\n**Rule:** Personalized offers evaluate alongside public rules. The member receives whichever combination yields better value.\n**Example:** Public 2x for Gold members vs. personalized 5x birthday offer → system applies the 5x.\n\n**Rule:** Delayed awards can be cancelled by refund events before processing. The Inngest workflow state is the pending state — no database pending table exists.\n**Example:** Merchant configures 24-hour delay. Member purchases, then refunds 2 hours later → `currency/cancelled` event cancels the sleeping workflow before any points are awarded.\n\n**Rule:** Points transactions always have `target_entity_id = NULL`. Ticket transactions always have `target_entity_id = ticket_type.id`. This separation is enforced at the database constraint level.\n**Example:** Single purchase awarding both → two separate ledger entries with different `target_entity_id` values.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/currency.md#L247 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "52197a8bc1b6fe9e8786a9592018c11c74afa9e97a2312f1e646804b214a5f5b", "truncated": false}, "is_active": true}, {"id": "bc87fc05-2e19-55b1-be75-40d79d715671", "feature_slug": "currency", "title": "3. Configuration Reference", "content": "### Earn Rate (Basic Mode)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Target currency | Points or a specific ticket type | `points` | Required |\n| Different rate per tier | Toggle tier-specific rates | true | false |\n| Single rate | Spend amount per 1 currency unit (when uniform) | 30 (THB per point) | — |\n| Per-tier rates | Rate per tier (when differentiated) | Gold=35, Silver=30, Platinum=25 | — |\n| Excluded products | Products/SKUs/brands/categories excluded from earning | [gift cards, sale items] | None |\n\n### Multipliers (Basic Mode)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Allow stacking | Whether multipliers combine or best-only | true | true |\n| Multiplier rate | Multiplication factor | 3 (= 3x) | — |\n| Active status | Enable/disable this multiplier | true | true |\n| Window start/end | Validity period | Jun 1 – Jun 30 | No restriction |\n| Timing | Day-of-week and hour constraints | Weekend (Sat, Sun) | All times |\n| Tiers | Which tiers qualify | [Gold, Platinum] | All tiers |\n| Include products | Products eligible for this multiplier | [shoes, accessories] | All products |\n\n### Expiry Settings\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Expiry enabled | Whether currency expires | true | false |\n| Expiry mode | TTL, fixed_frequency, or absolute | `ttl` | — |\n| TTL months | Months until expiry (TTL mode) | 12 | — |\n| Frequency | Period boundary (fixed mode) | `quarterly` | — |\n| Fiscal year end month | Fiscal calendar alignment | 6 (June) | 12 (December) |\n| Minimum period months | Earliest expiry protection | 3 | — |\n| Absolute expiry date | Fixed date (tickets only) | 2025-12-31 | — |\n\n### Award Timing\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Delay days | Calendar days before awarding | 1 | 0 (immediate) |\n| Delay minutes | Rolling minutes before awarding | 120 | 0 |\n| Award time | Specific time of day to award | 08:00 | — |\n| Award timezone | Timezone for time interpretation | Asia/Bangkok | — |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/currency.md#L45 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3c3d81a47d98277c861b45bda037ff5a0ec07d151c5315fc6d26df0988b06b65", "truncated": false}, "is_active": true}, {"id": "e04925ea-b0db-5cf7-b1fc-4a6c3a78589c", "feature_slug": "currency", "title": "Table of Contents", "content": "- [Glossary of Terms](#glossary-of-terms)\n- [Business Requirements](#business-requirements)\n  - [Loyalty Program Configuration Model](#loyalty-program-configuration-model)\n  - [Public Earning Rules vs Personalized Offers](#public-earning-rules-vs-personalized-offers)\n  - [Tier Integration and Benefits](#tier-integration-and-benefits---one-of-many-attributes)\n  - [Currency Expiry Management](#currency-expiry-management)\n    - [Daily Expiry Processing](#daily-expiry-processing)\n  - [Currency Reversal Management](#currency-reversal-management)\n- [Currency Calculation Engine](#1-currency-calculation-engine)\n- [Currency Award Service](#2-currency-award-service)\n  - [Durable Execution Architecture](#durable-execution-architecture)\n  - [Merchant Configuration for Delayed Awards](#merchant-configuration-for-delayed-awards)\n  - [Award Process (Inngest Workflow)](#award-process-inngest-workflow)\n  - [Workflow Observability](#workflow-observability)\n  - [Currency Reversal Handling](#currency-reversal-handling)\n- [System Operations](#system-operations)\n- [Business Rules Summary](#business-rules-summary)\n- [Implementation Examples](#implementation-examples)\n- [API Integration](#api-integration)\n- [Complete Transaction Flow](#currency---complete-transactions-to-currency-flow)\n- [Architecture Components](#architecture-components)\n- [Appendix: Technology Stack](#appendix-technology-stack)\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Currency.md#L14 Table of Contents", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e5912e557a223323745729aac95fcfe46ee2b49e7b488d64a0173f0874280ea0", "truncated": false}, "is_active": true}, {"id": "50ba15ee-1e0c-5dfe-82d9-e46b44c4a6d7", "feature_slug": "currency", "title": "API Integration", "content": "### Calculate Currency (Preview)\n```http\nGET /api/currency/calculate/{transaction_id}\n```\n\n**Response**:\n```json\n{\n  \"currencies\": {\n    \"points\": {\n      \"base\": 10,\n      \"final\": 44,\n      \"target_entity_id\": null,\n      \"breakdown\": {\n        \"base_calculation\": \"1000 THB ÷ 100 = 10 points\",\n        \"multipliers_applied\": [\n          {\n            \"type\": \"line_specific\",\n            \"factor\": 3,\n            \"amount_affected\": 300,\n            \"currency_added\": 9\n          },\n          {\n            \"type\": \"transaction_wide\",\n            \"factor\": 5,\n            \"amount_affected\": 700,\n            \"currency_added\": 35\n          }\n        ]\n      }\n    },\n    \"tickets\": {\n      \"types\": [\n        {\n          \"ticket_type_id\": \"c0000000-0000-0000-0000-000000000001\",\n          \"ticket_name\": \"Monthly Raffle\",\n          \"ticket_code\": \"RAFFLE_2024\",\n          \"base\": 5,\n          \"final\": 5\n        },\n        {\n          \"ticket_type_id\": \"c0000000-0000-0000-0000-000000000004\",\n          \"ticket_name\": \"Free Parking Pass\",\n          \"ticket_code\": \"PARKING\",\n          \"base\": 10,\n          \"final\": 20\n        }\n      ]\n    }\n  },\n  \"applied_factors\": {\n    \"rates\": [\n      {\n        \"id\": \"uuid\",\n        \"name\": \"Standard Rate\",\n        \"value\": 100\n      }\n    ],\n    \"multipliers\": [\n      {\n        \"id\": \"uuid\",\n        \"name\": \"Birthday Bonus\",\n        \"value\": 5,\n        \"scope\": \"transaction\"\n      }\n    ]\n  }\n}\n```\n\n### Award Currency (Process)\n```http\nPOST /api/currency/award/{transaction_id}\n```\n\n**Request Body** (optional overrides):\n```json\n{\n  \"processing_method\": \"direct|queue\",\n  \"delay_seconds\": 0\n}\n```\n\n**Response**:\n```json\n{\n  \"status\": \"awarded|queued\",\n  \"points_awarded\": 44,\n  \"tickets_awarded\": [\n    {\n      \"ticket_type_id\": \"c0000000-0000-0000-0000-000000000001\",\n      \"ticket_name\": \"Monthly Raffle\",\n      \"amount\": 5,\n      \"balance_after\": 15\n    },\n    {\n      \"ticket_type_id\": \"c0000000-0000-0000-0000-000000000004\",\n      \"ticket_name\": \"Free Parking Pass\",\n      \"amount\": 20,\n      \"balance_after\": 120\n    }\n  ],\n  \"points_balance_after\": 544,\n  \"queue_message_id\": \"msg_123\",\n  \"estimated_processing_time\": \"2024-01-15T10:30:00Z\",\n  \"message\": \"Currency successfully added to wallet\"\n}\n```\n\n### Check Currency Status\n```http\nGET /api/currency/status/{transaction_id}\n```\n\n**Response**:\n```json\n{\n  \"transaction_id\": \"uuid\",\n  \"status\": \"pending|processed|failed\",\n  \"points_calculated\": 44,\n  \"tickets_calculated\": 2,\n  \"points_awarded\": 44,\n  \"tickets_awarded\": 2,\n  \"processed_at\": \"2024-01-15T10:25:00Z\",\n  \"error\": null\n}\n```\n\n### Reverse Currency\n```http\nPOST /api/currency/reverse\n```\n\n**Request**:\n```json\n{\n  \"user_id\": \"uuid\",\n  \"merchant_id\": \"uuid\",\n  \"currency\": \"points|tickets\",\n  \"amount\": 100,\n  \"reason\": \"Order refund #12345\",\n  \"reference_id\": \"original_transaction_uuid\"\n}\n```\n\n### Staff POS Point-Discount Burn\n\nFE-callable BFF functions:\n- `bff_preview_point_discount_burn(p_user_id, p_points_amount)` calculates available points, tier burn rate, and discount amount without deducting points.\n- `bff_create_point_discount_burn(p_user_id, p_points_amount, p_store_id, p_description, p_metadata)` burns points and returns a POS-facing wallet code.\n- `bff_admin_get_point_discount_burn_history(p_user_id, p_store_id, p_minutes)` returns recent point-discount burn rows with use/reversal status.\n- `bff_reverse_point_discount_burn(p_wallet_ledger_id, p_code, p_reason, p_metadata)` returns points through a reversal earn row unless the code is attached to an active purchase.\n\nPermission rules: broad currency admins use `currency` permissions. Frontline admins use the scoped `frontline_burn_points_discount` permission; history accepts `read` or `update`, while preview/create/reverse require `update`.\n\n### Get Upcoming Expiries\n```http\nGET /api/currency/expiries/upcoming\n```\n\n**Query Parameters**:\n- `user_id`: Filter by specific user\n- `days`: Number of days ahead (default: 30)\n- `currency`: Filter by points or tickets\n\n**Response**:\n```json\n{\n  \"expiries\": [\n    {\n      \"currency\": \"points\",\n      \"amount\": 500,\n      \"expiry_date\": \"2024-03-31\",\n      \"days_until_expiry\": 15,\n      \"origin\": \"Purchase on 2023-09-30\"\n    },\n    {\n      \"currency\": \"tickets\",\n      \"ticket_type\": \"Monthly Raffle\",\n      \"amount\": 10,\n      \"expiry_date\": \"2024-04-30\",\n      \"days_until_expiry\": 45\n    }\n  ],\n  \"summary\": {\n    \"total_expiring_points\": 500,\n    \"total_expiring_tickets\": 10,\n    \"next_expiry_date\": \"2024-03-31\"\n  }\n}\n```\n\n### Configure Expiry Settings\n```http\nPUT /api/merchant/{merchant_id}/expiry-config\n```\n\n**Request Body**:\n```json\n{\n  \"points\": {\n    \"mode\": \"fixed_frequency\",\n    \"frequency\": \"quarterly\",\n    \"fiscal_year_end_month\": 6,\n    \"minimum_period_months\": 3,\n    \"active\": true\n  }\n}\n```\n\n### Get Expiry Configuration\n```http\nGET /api/merchant/{merchant_id}/expiry-config\n```\n\n**Response**:\n```json\n{\n  \"points\": {\n    \"mode\": \"ttl\",\n    \"ttl_months\": 12,\n    \"active\": true,\n    \"statistics\": {\n      \"upcoming_30_days\": 15000,\n      \"users_affected\": 234\n    }\n  },\n  \"tickets\": [\n    {\n      \"ticket_type_id\": \"uuid\",\n      \"ticket_name\": \"VIP Pass\",\n      \"mode\": \"absolute_date\",\n      \"absolute_date\": \"2024-12-31\",\n      \"upcoming_expiries\": 50\n    }\n  ]\n}\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Currency.md#L2202 API Integration", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "02efd99611906d668a3bd108c99a87080b319df08e9ba336031a1740fe56cc6e", "truncated": false}, "is_active": true}, {"id": "89a81422-f621-5e17-b5a2-deeb79a9b8f1", "feature_slug": "currency", "title": "Basic Currency Config — BFF Functions (Implemented)", "content": "### Overview\n\nTwo RPC functions provide a simplified interface for configuring earn rates and multipliers per currency type. They abstract the underlying `earn_factor_group`, `earn_factor`, `earn_conditions_group`, and `earn_conditions` tables into a single JSON blob that the FE stores as a local variable, edits, and sends back.\n\nThe same page serves points, store credit (ticket with `is_credit = true`), and other ticket types — the FE passes the appropriate `(target_currency, target_entity_id)` pair.\n\n### Architecture: 1 Group Per Currency Type\n\nEach `(target_currency, target_entity_id)` pair gets its own `earn_factor_group`. This ensures independent `stackable` settings and clean orphan cleanup without cross-currency interference.\n\n### Functions\n\n#### `bff_get_basic_currency_config(p_target_currency TEXT, p_target_entity_id UUID DEFAULT NULL)`\n\nReturns the current basic config for a merchant + currency type.\n\n**Detection logic:**\n1. Finds groups containing factors matching the currency type\n2. If 0 groups → returns empty skeleton (new mode)\n3. If 1 group → validates basic constraints → returns populated data\n4. If multiple groups → returns `{ \"mode\": \"not_basic\" }`\n\n**Validation constraints (must all pass for basic mode):**\n- Exactly 1 group for the currency type\n- Group contains only factors for this currency type (no mixed currencies)\n- All condition entity types are in: `tier`, `product_sku`, `product_product`, `product_brand`, `product_category`\n- Rate factors have no `window_start` / `window_end`\n\n#### `bff_upsert_basic_currency_config(p_config JSONB)`\n\nCreates or updates the full basic config in one transaction.\n\n**Operations performed:**\n- Upserts `earn_factor_group` (creates on first save, updates `stackable` on subsequent)\n- For per-tier rates: creates one `earn_factor` (type=rate) per tier, each with its own `earn_conditions_group` containing a tier condition and any excluded product conditions\n- For single rate: creates one `earn_factor` (type=rate) with optional excluded product conditions\n- For multipliers: creates one `earn_factor` (type=multiplier) per item, with optional conditions group for tiers and product includes\n- Handles `earn_factor_time_conditions` for multiplier timing (day_of_week, hour_start, hour_end)\n- Deletes factors no longer in the config\n- Cleans up orphaned conditions groups\n- Auto-deletes the group if all factors are removed\n\n### Shared JSON Shape (GET returns it, UPSERT accepts it)\n\n```json\n{\n  \"target_currency\": \"points\",\n  \"target_entity_id\": null,\n  \"earn_factor_group_id\": \"uuid | null\",\n  \"earn_rate\": {\n    \"different_rate_per_tier\": true,\n    \"single_rate\": null,\n    \"single_rate_factor_id\": \"uuid | null\",\n    \"rates\": [\n      {\n        \"factor_id\": \"uuid | null\",\n        \"tier_id\": \"uuid\",\n        \"tier_name\": \"Gold\",\n        \"earn_factor_amount\": 35,\n        \"earn_conditions_group_id\": \"uuid | null\"\n      }\n    ],\n    \"excluded_products\": [\n      {\n        \"condition_id\": \"uuid | null\",\n        \"entity\": \"product_sku\",\n        \"entity_ids\": [\"uuid\"]\n      }\n    ]\n  },\n  \"multipliers\": {\n    \"stackable\": true,\n    \"items\": [\n      {\n        \"factor_id\": \"uuid | null\",\n        \"active_status\": true,\n        \"earn_factor_amount\": 3,\n        \"window_start\": \"2024-07-20T00:00:00Z\",\n        \"window_end\": \"2024-07-20T23:59:59Z\",\n        \"earn_conditions_group_id\": \"uuid | null\",\n        \"timing\": {\n          \"day_of_week\": [0, 6],\n          \"hour_start\": 0,\n          \"hour_end\": 23\n        },\n        \"tiers\": [\n          { \"tier_id\": \"uuid\", \"tier_name\": \"Gold\" }\n        ],\n        \"include_products\": [\n          {\n            \"condition_id\": \"uuid | null\",\n            \"entity\": \"product_product\",\n            \"entity_ids\": [\"uuid\"]\n          }\n        ]\n      }\n    ]\n  }\n}\n```\n\n**Read-only fields** (returned by GET, ignored by UPSERT): `tier_name`, `entity_names`.\n\n### Backend Object Mapping\n\n| UI Element | Backend Object |\n|---|---|\n| Earn rate (single) | 1 `earn_factor` (type=rate), optional `earn_conditions_group` for excluded products |\n| Earn rate (per-tier) | N `earn_factor` (type=rate), each with `earn_conditions_group` containing tier + excluded product conditions |\n| Excluded products | `earn_conditions` rows with `exclude = true` in each rate factor''s conditions group |\n| Multiplier card | 1 `earn_factor` (type=multiplier) with optional `earn_conditions_group` for tiers + product includes |\n| Multiplier timing | `earn_factor_time_conditions` row linked to the multiplier factor |\n| Stackable toggle | `earn_factor_group.stackable` |\n\n### Also Updated: `exclude` Support in Existing Functions\n\n- `bff_get_earn_conditions_group` now returns `exclude` field per condition\n- `bff_upsert_earn_conditions_group` now accepts and writes `exclude` field (backward compatible — defaults to `false` if omitted)\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Currency.md#L3067 Basic Currency Config — BFF Functions (Implemented)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9d7197d617545f4557dd2e8472b89bb18fb5c857109153e2b4b470184e200b64", "truncated": false}, "is_active": true}, {"id": "0a7317a7-92ca-515c-a8b5-1d0b31d76c2f", "feature_slug": "currency", "title": "Appendix: Schema Changes (v2.1)", "content": "### Overview\nVersion 2.1 introduces UOM (Unit of Measure) threshold support for quantity-based and amount-based loyalty rules, enabling B2B and bulk purchase scenarios.\n\n### New Columns Added\n\n#### product_sku_master\n```sql\nALTER TABLE product_sku_master \nADD COLUMN IF NOT EXISTS uom_primary TEXT,\nADD COLUMN IF NOT EXISTS uom_secondary TEXT;\n\nCOMMENT ON COLUMN product_sku_master.uom_primary \n  IS ''Primary unit of measure code (e.g., STD, BAG, PIECE, KG)'';\nCOMMENT ON COLUMN product_sku_master.uom_secondary \n  IS ''Secondary/bulk unit of measure code (e.g., TON, PALLET, CONTAINER)'';\n```\n\n**Purpose**: Define measurement units for products\n**Examples**: \n- Primary: BAG, PIECE, BOTTLE, SACHET, CUP, BOX, JAR\n- Secondary: TON, PALLET, CARTON, CASE, TRAY\n\n#### purchase_items_ledger\n```sql\nALTER TABLE purchase_items_ledger \nADD COLUMN IF NOT EXISTS quantity_secondary NUMERIC;\n\nCOMMENT ON COLUMN purchase_items_ledger.quantity_secondary \n  IS ''Quantity in secondary UOM. The existing quantity field represents primary UOM.'';\n```\n\n**Purpose**: Store both primary and secondary measurements for same purchase line item\n**Note**: Existing `quantity` field unchanged (backward compatible)\n\n#### earn_conditions\n```sql\nALTER TABLE earn_conditions \nADD COLUMN IF NOT EXISTS threshold_unit TEXT \n  CHECK (threshold_unit IN (''quantity_primary'', ''quantity_secondary'', ''amount'')),\nADD COLUMN IF NOT EXISTS min_threshold NUMERIC,\nADD COLUMN IF NOT EXISTS max_threshold NUMERIC,\nADD COLUMN IF NOT EXISTS apply_to_excess_only BOOLEAN DEFAULT false;\n\nCOMMENT ON COLUMN earn_conditions.threshold_unit \n  IS ''What to check for threshold: quantity_primary (check quantity field), quantity_secondary (check quantity_secondary field), amount (check line_total)'';\nCOMMENT ON COLUMN earn_conditions.min_threshold \n  IS ''Minimum value required to qualify (quantity or amount depending on threshold_unit)'';\nCOMMENT ON COLUMN earn_conditions.max_threshold \n  IS ''Maximum eligible value cap (prevents abuse on very large purchases)'';\nCOMMENT ON COLUMN earn_conditions.apply_to_excess_only \n  IS ''When true: multiplier applies only to quantity/value above min_threshold. When false (default): multiplier applies to full matched item line value.'';\n```\n\n**Purpose**: Configure threshold rules for conditional loyalty bonuses\n\n### Function Updates\n\n#### evaluate_earn_conditions()\n**Changes**:\n- Added threshold checking logic for product conditions\n- Supports quantity_primary, quantity_secondary, and amount thresholds\n- Checks min_threshold before approving condition\n- Applies max_threshold cap if specified\n- Returns matched items with calculated totals\n\n**Backward Compatible**: NULL thresholds = original behavior (no threshold check)\n\n#### calc_currency_for_transaction()\n**Changes**:\n- Maintains existing calculation logic\n- Now references threshold-validated conditions from evaluate_earn_conditions()\n- No breaking changes to multiplier application\n\n**Backward Compatible**: Works unchanged with existing earn factors\n\n### Migration Safety\n\n**Additive Changes Only**:\n- ✅ All new columns are nullable with sensible defaults\n- ✅ Existing earn factors without thresholds work unchanged\n- ✅ Functions handle null threshold values gracefully\n- ✅ No breaking changes to existing functionality\n\n**Rollback Available**:\n- Functions can be restored to original versions\n- New columns can be dropped if needed\n- See: `/migrations/rollback_uom_thresholds.sql`\n\n### Configuration Examples\n\n#### Example 1: Quantity Threshold (Primary UOM)\n```sql\n-- Product with UOMs\nUPDATE product_sku_master \nSET uom_primary = ''BAG'', uom_secondary = ''TON''\nWHERE sku_code = ''CEMENT-001'';\n\n-- Condition: Buy ≥50 bags\nINSERT INTO earn_conditions (\n  entity, entity_ids, threshold_unit, min_threshold, apply_to_excess_only\n) VALUES (\n  ''product_sku'', ARRAY[''<sku_uuid>''], \n  ''quantity_primary'', 50, false\n);\n\n-- Result: 5x multiplier applies to full line value if qty ≥ 50\n```\n\n#### Example 2: Secondary UOM with Excess Mode\n```sql\n-- Condition: Buy ≥2 tonnes, bonus on excess only\nINSERT INTO earn_conditions (\n  entity, entity_ids, threshold_unit, min_threshold, apply_to_excess_only\n) VALUES (\n  ''product_sku'', ARRAY[''<steel_sku_uuid>''], \n  ''quantity_secondary'', 2, true\n);\n\n-- Result: If buy 3 tonnes, 10x multiplier applies only to 1 tonne excess\n```\n\n#### Example 3: Amount Threshold with Cap\n```sql\n-- Condition: Spend ≥5000 THB, max 50000 THB\nINSERT INTO earn_conditions (\n  entity, entity_ids, threshold_unit, min_threshold, max_threshold\n) VALUES (\n  ''product_category'', ARRAY[''<electronics_uuid>''], \n  ''amount'', 5000, 50000\n);\n\n-- Result: 3x multiplier applies, but capped at 50k even if spend 80k\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Currency.md#L3347 Appendix: Schema Changes (v2.1)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3bb7e5ebafa9c9da254dc3e2370ba8665598959e1ce41a0b5e2a6f1584b23140", "truncated": false}, "is_active": true}, {"id": "6d6a4aa5-2f55-5899-93ab-f3a0df6fe99c", "feature_slug": "currency", "title": "2. Key Concepts", "content": "**Points** — Fungible loyalty currency. All points are interchangeable, stored as a single balance per member. Used for reward redemption and tier progression. Example: Member has 500 points → redeems 200 → balance is 300.\n\n**Tickets** — Non-fungible currency where each type is distinct. Each ticket type (e.g., \"Christmas Raffle\", \"VIP Access\") has its own independent balance. Cannot be exchanged between types. Example: Member has 5 raffle tickets and 2 VIP passes — these are separate, unrelated balances.\n\n**Earn Factor** — A rule determining how members earn currency. Two types: *rate factors* convert spend to currency (\"100 THB = 1 point\"), and *multiplier factors* boost earnings by a multiplication factor (\"3x on shoes\"). Each factor can target points or a specific ticket type.\n\n**Earn Factor Group** — A container bundling related earn factors with shared properties: validity window, stacking behavior, and activation status. Individual factors inherit group settings unless explicitly overridden.\n\n**Earn Conditions** — Qualifying criteria for an earn factor: tier level, product SKU/brand/category, store attributes, or persona. An `exclude` flag can invert a condition to remove specific items from eligibility. Empty conditions = applies to entire transaction.\n\n**Stackable** — A group-level setting controlling multiplier interaction. When true, multipliers combine additively (2x + 1.5x = 3.5x total). When false, only the best multiplier per scope applies — though one product-specific and one transaction-wide multiplier can coexist since they operate on mutually exclusive portions of the transaction amount.\n\n**Multiplier Calculation Mode** — Merchant-level setting (`multiplier_additive`). *Total Rate mode* (default): 5x multiplier on 10 base = 50 total (5 times base). *Additive mode*: 5x on 10 base = 60 total (base + 5 times base).\n\n**Components** — How currency is categorized in the wallet: `base` (from rate conversion), `bonus` (from multipliers), `adjustment` (admin corrections), `reversal` (refund deductions).\n\n**Signed Amount** — Directional value on ledger entries. Positive for earning, negative for burns and reversals. The `amount` field is always the absolute value.\n\n**Source Types** — Origin of a wallet transaction: `purchase` (buying products), `referral` (referral bonuses), `mission` (task completion), `campaign` (bulk awards), `manual` (admin adjustments).\n\n**Personalized Offers** — Private earn factors assigned to specific members via `earn_factor_user`. Evaluated alongside public rules; the better value applies. Example: Birthday month 5x multiplier assigned only to the birthday member.\n\n**Expiry Modes** — Three ways currency can expire: *TTL* (X months after earning), *Fixed Frequency* (at fiscal period boundaries — monthly, quarterly, semi-annual, annual), *Absolute Date* (tickets only, all expire on a specific date).\n\n**Minimum Period Protection** — Prevents recently earned currency from immediate expiry in fixed frequency mode. Example: Points earned in November with quarterly expiry and 6-month minimum won''t expire until the following May.\n\n**Deductible Balance** — The remaining usable portion of a currency award that is subject to expiry. Original amount minus any redemptions already made against it.\n\n**Credit Ticket Type** — A ticket type where `is_credit = true`. Redemption triggers an external platform credit API call (e.g., Shopify store credit) instead of a standard wallet burn. One credit ticket type per platform per merchant.\n\n**Ticket Codes** — Unique printable codes (e.g., `SYN-A7X3B2`) assigned to individual ticket earnings, used for raffles and event campaigns. Codes are pre-generated into a pool and assigned atomically using `FOR UPDATE SKIP LOCKED`.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/currency.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e70e993742fb6e018e8bb7400bd5706dcb9713db2dd7b0b1d5bdad043b3bc208", "truncated": false}, "is_active": true}, {"id": "c2b46b48-b951-5a33-831d-3151ef0b839f", "feature_slug": "currency", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch**: \"Members earn points and tickets automatically when they shop or complete activities. The system calculates how much to award based on the rules you''ve set up — earn rates, multipliers, and bonus campaigns. Members see their balance on the app homepage and can check full history in the wallet.\"\n\n**Top 5 support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Member didn''t receive points after purchase\" | Check award timing config — merchant may have delayed awards (next day at 8 AM). Also verify the transaction completed successfully in purchase ledger. |\n| \"Points amount seems wrong\" | Check which earn rate and multipliers applied. The system always picks the best rate for the member. Review the transaction in currency history for applied factors. |\n| \"Points expired unexpectedly\" | Check expiry mode (TTL, quarterly, etc.) and minimum period protection. Expiry runs daily at 2 AM. Only the unused portion expires — any redeemed amount is protected. |\n| \"Member has tickets but can''t see them\" | Tickets display separately from points. Check the Currency tab in History — tickets appear under their own sub-filter. Verify the ticket type is still active. |\n| \"Refund processed but points not reversed\" | Reversals are proportional to refund amount and use the original earn rate (not current rates). Check if the reversal workflow completed in the system. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/currency.md#L171 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "04459fcf0f69fd183371667cdb5266923df7fc124a2072de7a731d423d253988", "truncated": false}, "is_active": true}, {"id": "1cc6f37c-08bb-5a49-9896-1c7d5c77cc20", "feature_slug": "currency", "title": "1. Overview", "content": "Currency is the \"earn\" side of the loyalty loop — the mechanism that converts member activity into tangible value they can later spend on rewards. When a member makes a purchase, completes a mission, or refers a friend, the system calculates how much currency to award based on merchant-configured earn rules, then records it to the member''s wallet. This is the engine that makes every other loyalty feature meaningful: tiers need points to track progress, rewards need points to redeem, and campaigns need points to incentivize.\n\nThe platform supports two currency types with fundamentally different behaviors. Points are fungible — all points are interchangeable and stored as a single balance. Tickets are non-fungible — each ticket type (raffle entries, VIP passes, parking passes) maintains an independent balance, and tickets cannot be exchanged between types. A single purchase can award both points and multiple ticket types simultaneously, each calculated and tracked separately.\n\nMerchants control earning through a layered rule system: rate factors set the base conversion (e.g., \"spend 100 THB = 1 point\"), multiplier factors boost earnings for specific conditions (e.g., \"3x on weekends for Gold members\"), and expiry rules manage liability by expiring unused currency after configurable periods. The system processes awards through a durable execution pipeline — purchases flow through CDC, calculation, and Inngest workflows — supporting delayed awards, automatic cancellation on refunds, and four-level idempotency guarantees.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/currency.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "17b83cb3dd2bbe3707b605d18611507d8bde00201f8c38c653e6991bd327964a", "truncated": false}, "is_active": true}, {"id": "b2ca3037-6436-5bc1-9b5b-57735492b4de", "feature_slug": "currency", "title": "8. Related Features", "content": "| Feature | Connection to Currency |\n|---|---|\n| Rewards | Points are deducted from the member''s wallet upon redemption (the \"burn\" side of earn-and-burn). See `Reward.md`. |\n| Tier | Tier determines eligible earn rates and multipliers. Points earned contribute to tier progression. See `Tier.md`. |\n| Purchase | Purchase transactions are the primary source triggering currency calculation. See `Purchase_Transaction.md`. |\n| Activity/Earning | Activity-based earning (receipt upload, marketplace claims, QR scans) awards currency through the same pipeline. See `Activity_Based_Earning.md`. |\n| Mission | Mission completion awards currency via `source_type = ''mission''`. See `Mission.md`. |\n| Referral | Referral bonuses award currency via `source_type = ''referral''` to both inviter and invitee. See `Referral.md`. |\n| Tag & Persona | Personas and tags are earn condition dimensions — multipliers and rates can target specific segments. See `Tag_and_Persona.md`. |\n| Store Classification | Store attributes act as earn condition dimensions for location-based multipliers. See `Store_Attribute_Classification.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/currency.md#L276 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "93014d0544d3fb93bc27ae1b9fdf8cb525e35e7bcf2c0cd257b8d5cc6213ceba", "truncated": false}, "is_active": true}, {"id": "64568ee3-e7ce-5158-817a-9db5230fcee4", "feature_slug": "currency", "title": "Currency - Complete Transactions to Currency Flow", "content": "### Core Architecture: Event Capture + Durable Execution\n\n**CDC Path for database-backed sources**:\nData Change → CDC → Kafka → Render Consumer → Inngest → Wallet\n\nPurchase, referral, and mission awards are captured from database changes through CDC/Kafka and processed by Render `crm-event-processors`. Campaign and manual awards may publish directly to Inngest because their award amount is already explicit in the request metadata. All sources converge at `inngest-currency-serve` for durable waiting, cancellation, wallet posting, and workflow logging.\n\n### Complete System Flow Diagram\n\n```mermaid\ngraph TB\n    subgraph \"Event Sources\"\n        PUR[Purchase Completed]\n        REF[Referral Processed]\n        MIS[Mission Claimed]\n        CAM[Campaign/Manual]\n    end\n    \n    subgraph \"CDC Layer\"\n        CDC1[Confluent CDC<br/>Debezium Connector]\n        KFK[Kafka Topics]\n    end\n    \n    subgraph \"Durable Execution\"\n        INN[Inngest Cloud]\n        SRV[inngest-currency-serve<br/>Edge Function]\n        AWD[currency-award workflow]\n        REV[currency-reversal workflow]\n    end\n    \n    subgraph \"Configuration\"\n        CFG[get-merchant-config<br/>Edge Function]\n        REDIS[Upstash Redis Cache]\n        MM[merchant_master]\n    end\n    \n    subgraph \"Calculation\"\n        CALC[calc_currency_for_source]\n        TRANS[calc_currency_for_transaction]\n        GEF[get_eligible_earn_factors]\n        MV[Materialized Views]\n    end\n    \n    subgraph \"Wallet Layer\"\n        POST[post_wallet_transaction]\n        WL[wallet_ledger]\n        UW[user_wallet]\n        UTB[user_ticket_balances]\n        TIER[trigger_tier_eval_on_wallet]\n    end\n    \n    subgraph \"Observability\"\n        LOG[inngest_workflow_log]\n    end\n    \n    PUR --> CDC1\n    REF --> CDC1\n    MIS --> CDC1\n    CDC1 --> KFK\n    KFK --> CON[Render Consumer]\n    CON --> CFG\n    CON --> CALC\n    CON --> INN\n    CAM --> INN\n    INN --> SRV\n    SRV --> AWD & REV\n    \n    CFG --> REDIS\n    REDIS -.-> MM\n    \n    CALC --> TRANS\n    TRANS --> GEF\n    GEF --> MV\n    \n    AWD --> POST\n    REV --> POST\n    POST --> WL\n    POST --> UW\n    POST --> UTB\n    WL --> TIER\n    \n    AWD & REV --> LOG\n```\n\n### Step-by-Step Flow\n\n#### Step 1: CDC Captures Data Changes\n\n**Purchase Events**:\n- Confluent CDC (Debezium) captures INSERT/UPDATE on `purchase_ledger`\n- Publishes to Kafka topic `crm.public.purchase_ledger`\n\n**Referral Events**:\n- Confluent CDC captures INSERT/UPDATE on `referral_ledger`\n- Publishes to Kafka topic `crm.public.referral_ledger`\n\n**Mission Events**:\n- Confluent CDC captures INSERT/UPDATE on `mission_claims`\n- Publishes to Kafka topic `crm.public.mission_claims`\n\n#### Step 2: Render Consumer Processes Events\n\n**CurrencyConsumer** in `crm-event-processors`:\n- Consumes CDC events from Kafka\n- Parses Debezium message format\n- Extracts source info (source_type, source_id, user_id, merchant_id)\n- Applies topic-specific filtering. For purchases: `earn_currency=true` and status in `pending`, `processing`, or `completed`; the calculation RPC then filters by `earn_factor.allowed_purchase_statuses`.\n- Deduplicates via Redis. Purchase keys include status (`source_type + source_id + status`); other source types use `source_type + source_id`.\n- Calculates currency via `calc_currency_for_source` RPC\n- Determines award timing from merchant config\n- Publishes `currency/award` event to Inngest\n\n#### Step 3: Inngest Workflow Execution\n\n**Workflow**: `currency-award` in `inngest-currency-serve`\n\n1. **Log Start**:\n   - Insert to `inngest_workflow_log` with status=''started''\n   - Store `inngest_run_id` for cross-reference\n\n2. **Use Award Input**:\n   - Read `currency_rows` and `award_datetime` from the `currency/award` event\n   - Do not consume Kafka or decide purchase eligibility inside Inngest\n\n3. **Optional Fallback Calculation**:\n   - If a legacy event does not include `currency_rows`, call `calc_currency_for_source` as a temporary compatibility fallback\n   - New producers must send pre-calculated `currency_rows`\n\n4. **Apply Delay (if configured)**:\n   - Use the consumer-provided `award_datetime`\n   - If delay needed: `step.sleepUntil(''wait-for-award-time'', award_datetime)`\n   - Workflow state persisted by Inngest during sleep\n   - Can be cancelled via `currency/cancelled` event\n\n5. **Award Each Currency**:\n   - For each row from calculation\n   - Call `post_wallet_transaction` RPC\n   - Each award is a separate Inngest step (individually retriable)\n\n6. **Log Completion**:\n   - Update `inngest_workflow_log` with status=''completed''\n   - Store results in metadata JSONB\n\n#### Step 4: Wallet Update\n\n**Function**: `post_wallet_transaction()`\n\nThis is the financial engine that:\n\n1. **Creates/Updates Wallet**:\n   - Inserts into `user_wallet` if not exists\n   - Uses row-level locking (SELECT FOR UPDATE) for concurrency\n\n2. **Calculates Expiry Date**:\n   - For points: Based on merchant''s `points_expiry_*` settings\n   - For tickets: Based on ticket type''s expiry configuration\n   - Expiry must succeed for award to proceed (atomic)\n\n3. **Updates Balance**:\n   - Calculates signed amount (+ for earn, - for burn)\n   - Points: Updates `user_wallet.points_balance`\n   - Tickets: Updates specific row in `user_ticket_balances`\n   - Prevents negative balances\n\n4. **Creates Ledger Entry**:\n   - Records in `wallet_ledger` with full metadata\n   - Includes `workflow_run_id` for Inngest traceability\n   - Stores balance before/after for audit\n\n5. **Idempotency Protection**:\n   - Unique constraint includes `currency` column\n   - Allows same purchase to award both points AND tickets\n   - Prevents double-awarding same currency type\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Currency.md#L2445 Currency - Complete Transactions to Currency Flow", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "03e6242a67251b4e9436dac0d88fec1a1647c6cafdccfb7dc8c3472fa4b2147c", "truncated": false}, "is_active": true}, {"id": "ab85d4ba-19dc-5d4a-b4e7-551c8e9bc391", "feature_slug": "currency", "title": "Architecture Components", "content": "### Render Consumer (`crm-event-processors`)\n\n#### CurrencyConsumer\n**Purpose**: Consumes CDC events and orchestrates currency awards\n- Repository: `Rocket-CRM/crm-event-processors`\n- Runtime: Render web service / worker connected to Confluent Kafka\n- Subscribes to Kafka topics: `crm.public.purchase_ledger`, `crm.public.referral_ledger`, `crm.public.mission_claims` (current deployed code may subscribe to purchase only)\n- **Deduplication**: Redis-based, 5-minute window. Purchase keys include status; other source types use source ID only.\n- **Calculation**: Calls `calc_currency_for_source` RPC\n- **Timing**: Fetches merchant config and calculates award datetime\n- **Publishing**: Sends `currency/award` event to Inngest with all context\n\n**Source Extraction by Topic**:\n| Topic | Source Type | User Field | Filters |\n|-------|-------------|------------|---------|\n| `crm.public.purchase_ledger` | purchase | user_id | `earn_currency=true`; status is `pending`, `processing`, or `completed`; RPC filters factors by `allowed_purchase_statuses` |\n| `referral_ledger` | referral | invitee_user_id | reward_status=''completed'' |\n| `mission_claims` | mission | user_id | status=''approved'' |\n\n### Edge Functions\n\n#### inngest-currency-serve\n**Purpose**: Hosts Inngest workflows for currency processing\n- `currency-award` workflow: Handles all award scenarios\n- `currency-reversal` workflow: Handles refund/cancellation reversals\n- Includes step-level retries (3 attempts per step)\n- `cancelOn` with precise matching (`source_type + source_id`) for aborting pending awards\n- **No pending table**: Inngest workflow state IS the pending state\n- Input comes from Render `CurrencyConsumer`. The workflow should award provided `currency_rows` after `award_datetime`; it is not the Kafka consumer and should not own purchase status filtering.\n\n#### get-merchant-config (or cached in consumer)\n**Purpose**: Provides cached merchant configuration\n- Redis cache with TTL-based refresh\n- Returns currency delay settings, expiry config, etc.\n\n### Database Functions\n\n#### calc_currency_core\n**Purpose**: Pure calculation engine — returns what a user would earn without writing anything\n- Input: `(merchant_id, user_id, amount, store_id, items_jsonb)`\n- Returns TABLE of `(currency_type, component, amount, earn_factor_id, target_entity_id)`\n- Status-agnostic: does not check purchase status, purely evaluates earn factors and multipliers\n- Use as a **preview endpoint**: call with draft order data to show \"You''ll earn X points and Y tickets\" before committing\n- Evaluates eligible rate factors (best rate wins per currency type) and multiplier factors (stackable/non-stackable)\n- For tickets: returns `target_entity_id` = ticket_type.id to identify which ticket type\n\n#### calc_currency_for_source\n**Purpose**: Central dispatcher for currency calculation\n- Routes to appropriate calculation based on source_type\n- Handles all unified source types (purchase, referral, mission, campaign, manual)\n\n#### calc_currency_for_transaction\n**Purpose**: Purchase-specific calculation with earn factors\n- Loads purchase amount, user, merchant, store, and items from `purchase_ledger` / `purchase_items_ledger`\n- Calls `calc_currency_core` internally for pure calculation\n- Returns calculated rows only; it does not post wallet transactions\n- Purchase status eligibility is enforced by the Render `CurrencyConsumer` using `earn_factor.allowed_purchase_statuses`, not by this pure calculation function\n\n#### post_wallet_transaction\n**Purpose**: Atomic wallet update with ledger entry\n- Updates balance with row-level locking\n- Calculates expiry dates inline\n- Creates audit trail in wallet_ledger\n\n#### fn_generate_ticket_codes\n**Purpose**: Pre-generate a pool of unique random codes for a ticket type\n- Input: `(merchant_id, ticket_type_id, quantity, prefix, code_length)`\n- Generates codes in format `{prefix}{random}` using charset excluding ambiguous characters\n- Handles collisions via retry; returns count of successfully generated codes\n\n#### fn_assign_ticket_codes\n**Purpose**: Assign codes from pool to a user when tickets are earned\n- Input: `(merchant_id, ticket_type_id, user_id, quantity, wallet_ledger_id, source_id)`\n- Atomic reservation using `FOR UPDATE SKIP LOCKED` (same pattern as reward promo codes)\n- Bidirectional stamping: marks `ticket_code.assigned_status = true` AND stamps codes into `wallet_ledger.metadata.ticket_codes`\n- Fails cleanly if insufficient codes in pool (no partial assignment)\n\n### External Services\n\n#### Confluent Cloud (CDC)\n**Purpose**: Change Data Capture\n- Debezium-based PostgreSQL source connector\n- Captures INSERT/UPDATE operations on source tables\n- Publishes to Kafka topics with guaranteed ordering\n\n#### Kafka\n**Purpose**: Durable event streaming\n- Topics per source table (e.g., `crm.public.purchase_ledger`)\n- Consumer group management for parallel processing\n- Message replay capability for recovery\n\n#### Inngest\n**Purpose**: Durable workflow execution\n- Orchestrates multi-step award workflows\n- **Workflow state IS the pending state** - no database table needed\n- Provides `sleepUntil` for delayed awards\n- `cancelOn` enables workflow cancellation via event matching\n- Maintains execution history\n\n#### Upstash Redis\n**Purpose**: Deduplication + Configuration caching\n- **Consumer dedup**: 5-minute window per source event\n- **Config cache**: Merchant settings with TTL\n- Reduces database load for hot paths\n\n### Supporting Components\n\n#### Materialized Views (Performance Optimization)\n- `mv_earn_factors_complete` - Pre-computed eligible factors with inheritance resolved\n- `mv_earn_factor_users` - Active personalized offer assignments\n- Refreshed every 5-15 minutes via scheduled jobs\n\n#### Observability Table\n- `inngest_workflow_log` - Tracks all workflow executions with Inngest run IDs\n\n### Why This Architecture Works\n\n#### Single Responsibility:\n1. `CurrencyConsumer` (Render) - Consumes CDC events, calculates currency, publishes to Inngest\n2. `inngest-currency-serve` - ONLY orchestrates workflow, waits if delayed, awards via RPC\n3. `calc_currency_for_source` - ONLY calculates, doesn''t award\n4. `post_wallet_transaction` - ONLY updates wallet, doesn''t calculate\n\n#### Separation of Concerns:\n- Event Capture (CDC) separate from Event Processing (Consumer)\n- Calculation (Consumer + RPC) separate from Award Execution (Inngest)\n- Pending State (Inngest workflow) separate from Business State (Database)\n- Configuration (Redis cache) separate from Source of Truth (Postgres)\n\n#### Benefits:\n- **Durability**: Inngest persists workflow state, survives restarts\n- **No Pending Table**: Inngest workflow state IS the pending state - simpler architecture\n- **Observability**: Every workflow logged with run ID for debugging\n- **Flexibility**: Delayed awards, cancellation via `cancelOn`, retries all supported\n- **Scalability**: Kafka + Consumer handles high throughput\n- **Consistency**: All sources use same CDC → Consumer → Inngest pipeline\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Currency.md#L2623 Architecture Components", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b72643391933b31011d09ee2db85bc611a00eff87c00e28a294312735fd7372d", "truncated": true}, "is_active": true}, {"id": "9734f6fc-a0fd-5ebc-b4e5-7f62529fae99", "feature_slug": "currency", "title": "Currency Domain Reference", "content": "**Keywords:** points, tickets, balance, earn, burn, wallet, earn factor, multiplier, rate, expiry, TTL, fixed frequency, reversal, refund, wallet ledger, source type, ticket type, credit ticket, deductible balance, wallet code, POS discount\n**Source:** `Currency.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `post_wallet_transaction(...)` | `p_user_id`, `p_merchant_id`, `p_currency`, `p_transaction_type`, `p_component`, `p_amount`, `p_source_type`, `p_source_id`, etc. | Wallet ledger entry with balance_before/after | 594 |\n| `bff_preview_point_discount_burn(...)` | `p_user_id`, `p_points_amount` | Calculates available points, tier burn rate, and discount amount without deducting points |\n| `bff_create_point_discount_burn(...)` | `p_user_id`, `p_points_amount`, optional `p_store_id`, `p_description`, `p_metadata` | Burns points, stores `wallet_ledger.code` + `discount_amount`, returns POS code |\n| `bff_reverse_point_discount_burn(...)` | `p_wallet_ledger_id` or `p_code`, optional `p_reason`, `p_metadata` | Returns points through an earn/reversal row unless code is attached to an active purchase |\n| `bff_admin_get_point_discount_burn_history(...)` | `p_user_id`, optional `p_store_id`, `p_minutes` | Returns recent POS point-discount burn rows and reversal/use status |\n**Key Business Rules (summary):**\n- Points are fungible; tickets are non-fungible (each type has independent balance via `target_entity_id`)\n- Earn factors: rate (conversion) and multiplier (bonus); can be public or personalized per user\n- `signed_amount`: positive for earn, negative for burn/reversal; `amount` always positive\n- Reversals use original calculation metadata (historical rates, not current) for fairness\n- Expiry processes daily at 2 AM; creates `burn` entries with `component=''expiry''`\n- Components: `base`, `bonus`, `adjustment`, `reversal`\n- Source types: `purchase`, `referral`, `mission`, `campaign`, `manual`, `activity`, `reward_redemption`\n- Staff POS point-discount burns store a human-facing `wallet_ledger.code` and the calculated cash `discount_amount` on the burn row. POS orders copy that code into `purchase_ledger.wallet_ledger_code` for reconciliation.\n- Wrong staff point-discount burns are reversed by creating a new wallet earn row with `component=''reversal''` and `reference_id` pointing to the original burn; the original burn is not deleted.\n- Point-discount BFFs allow broad currency admins via `currency` permissions and frontline admins via scoped `frontline_burn_points_discount` permissions. History accepts `read` or `update`; preview, create, and reverse require `update`.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/currency.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "810c9a98798938c8b2f94b4acba146570a79fa6ba13740ccde16e91054b37ca6", "truncated": false}, "is_active": true}, {"id": "d2b5d2ba-b808-5c78-8917-95f3cf56aa37", "feature_slug": "currency", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Rate = 100 THB/pt, purchase 500 THB | 5 points awarded (base component) |\n| Rate = 100, multiplier = 3x, stackable = true | Base 5 + bonus 10 = 15 points |\n| Two multipliers (2x, 3x), stackable = false | Best multiplier (3x) wins → base 5 + bonus 10 |\n| Non-stackable, product multiplier 3x on shoes (200 THB), transaction multiplier 5x | Shoes: 2 × 3 = 6 pts. Remainder (300 THB): 3 × 5 = 15 pts. Total: 21 |\n| `multiplier_additive = false`, 5x on 10 base | 50 total (5 × base) |\n| `multiplier_additive = true`, 5x on 10 base | 60 total (base + 5 × base) |\n| Delay days = 1, award time = 08:00 | Points appear next day at 8 AM, not immediately |\n| Refund 50% of purchase | 50% of original points reversed (using historical rate) |\n| Expiry mode = TTL, 6 months, earned Jan 15 | Expires Jul 15. Only unused portion expires. |\n| Expiry mode = fixed_frequency quarterly, min 3 months, earned May 15 | Expires Sep 30 (next quarter, respects minimum) |\n| Ticket type with absolute expiry Dec 31 | All tickets of this type expire Dec 31 regardless of earn date |\n| Purchase earns both points and tickets | Separate ledger entries with correct `target_entity_id` (null for points, UUID for tickets) |\n\n**Business rules as assertions:**\n\n- ASSERT: Only one rate factor per currency type applies — the best rate (lowest spend per unit) wins\n- ASSERT: Product-specific multipliers consume their portion; transaction-wide multipliers apply to remainder only\n- ASSERT: Reversals use historical calculation data from `wallet_ledger.metadata`, not current earn factors\n- ASSERT: Reversal amount = original amount × (refund amount / purchase amount)\n- ASSERT: Points `target_entity_id` is always NULL; tickets always have a `ticket_type.id`\n- ASSERT: Each ticket type balance is independent — earning raffle tickets does not affect parking passes\n- ASSERT: Expiry processes only the deductible balance (original minus redeemed)\n- ASSERT: Minimum period protection overrides fiscal period end dates\n- ASSERT: Four-level idempotency prevents duplicate awards (Kafka offset → Redis dedup → Inngest event ID → DB unique constraint)\n- ASSERT: `cancelOn` matches `source_type + source_id` precisely — cancelling one refund does not affect other pending awards\n\n**Transaction type model:**\n\n| Field | Values | Meaning |\n|---|---|---|\n| `transaction_type` | `earn`, `burn` | Direction of currency flow |\n| `component` | `base`, `bonus`, `adjustment`, `reversal` | Category of transaction |\n| `signed_amount` | Positive (earn) / Negative (burn, reversal) | Directional ledger value |\n| `currency` | `points`, `tickets` | Currency type |\n| `target_entity_id` | NULL (points) / UUID (tickets) | Ticket type linkage |", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/currency.md#L171 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8a3b70cfbb598cbc5e9d3b1d552e86704662de049be2bde5e65fcd6f7ad0beaa", "truncated": false}, "is_active": true}, {"id": "d784c010-b7a2-5192-8dfe-93c5382d457e", "feature_slug": "currency", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| Homepage Profile Card | `/` | `bff_get_display_blocks_cached(p_page: ''homepage'')` |\n| Wallet Drawer | Bottom-sheet from Homepage | `bff_get_reward_history()`, `bff_get_currency_history()` |\n| History Drawer | Bottom-sheet from Homepage/Profile | `bff_get_currency_history()`, `bff_get_user_history_menu()` |\n| Earn Drawer | Bottom-sheet from navigation | `bff_get_earn_channels()` |\n\n### 5a. View Points Balance\n\n1. Member opens the app — **Homepage** displays a Profile Card block\n2. Profile Card shows: tier name (gradient text), current points balance (large number with star icon), progress to next tier, and persona badge\n3. Points balance updates after each earn/burn event\n\n### 5b. View Wallet and History\n\n1. Member taps the History link on the points card → **Wallet Drawer** opens as a bottom-sheet\n2. Wallet header shows: tier card, points balance card, and a \"Redeem\" button\n3. Tabs: My Rewards, Packages, Benefits — each with filtered lists\n4. Tapping \"History\" opens a full-screen overlay with tabs: Point, Reward, Package, Campaign, Expired\n5. Currency history shows each transaction as a row: title, source, date, and signed amount badges (+/- with color coding)\n6. Sub-filters on Currency tab: Points, Tickets (dynamically generated per ticket type)\n\n### 5c. Earn Points via Channels\n\n1. Member taps an earn navigation item → **Earn Drawer** opens\n2. Tabs show available earn methods: receipt upload, marketplace order claim, QR code scan, referral, external links\n3. Each method has its own screen within the drawer\n4. On successful earn: success popup displays with points/tickets awarded", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/currency.md#L136 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "cbaa1587630006749d1ef77b0439ae0e49ef28f97ac20c34a44835728854b8f8", "truncated": false}, "is_active": true}, {"id": "ed61df26-c03b-5356-93cb-aece78a9ba67", "feature_slug": "currency", "title": "6b. For Marketing", "content": "**Value proposition**: Currency turns every purchase into a reason to return. Members earn points at rates the merchant controls — from simple flat rates to multi-dimensional rules that reward specific products, tiers, time windows, and personas differently. The multiplier system enables promotional campaigns (\"Double Points Weekend\") without changing base program economics.\n\n**Use-case stories:**\n\n1. **Café chain** — Sets base rate at 25 THB per point. Gold members earn at 20 THB per point (better rate). Weekend multiplier of 2x drives Saturday traffic. Birthday members get personalized 5x offers.\n\n2. **B2B distributor** — Uses quantity thresholds: \"Buy 50+ bags of cement → 5x points.\" Secondary UOM thresholds handle bulk: \"Buy 2+ tonnes → 10x.\" Product-specific multipliers promote high-margin items without inflating points on commodities.\n\n3. **Event venue** — Awards both points and event-specific tickets simultaneously from a single purchase. Raffle tickets (non-fungible, code-assigned) for prize draws, parking passes for convenience, and points for the general rewards catalog.\n\n**Differentiators:**\n- **Dual currency model** — fungible points and non-fungible tickets from the same transaction\n- **Multi-dimensional earn rules** — tier, product, store, persona, and time conditions compose freely\n- **Delayed award support** — merchants can hold points for 24 hours, enabling refund-window protection before awarding\n- **Durable execution** — four-level idempotency guarantees exactly-once processing at any scale", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/currency.md#L171 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "currency", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d7d687a6d6c39437bef7c881492ebff7cd73fbc5f4be9b2b67791b5f4d3889a0", "truncated": false}, "is_active": true}, {"id": "02470956-ec3c-5419-8483-28b538dc5856", "feature_slug": "customer-import", "title": "Customer Import / Export Domain Reference", "content": "**Keywords:** customer import, user import, bulk import, bulk upload, migration, csv import, csv export, user_import_staging, bulk_import_batches, bulk_upsert_customers_from_import, process_user_import_chunk, allow_bulk_import, skip_cdc, skip_side_effects, app.skip_side_effects, app.import_batch_id, ongoing import, migration mode, field selection, user_io_schemas, two-row header\n**Source:** Lives entirely in this file (no standalone source doc).\n|---|---|---|---|---|---|---|\n| `ongoing` | Day-to-day merchant uploads | published | fire normally | created by trigger | created by trigger | enqueued |\n| `migration` | Bulk migration from another CRM (10k–1M+ rows) | suppressed (`skip_cdc=true`) | suppressed via `app.skip_side_effects=true` | **skipped during write**, optionally backfilled in batch | **skipped entirely** unless explicitly opted in | suppressed; optional batch backfill |\n|---|---|---|\n|---|---|\n| `user_accounts_<col>` | `user_accounts` table |\n| `user_address_<col>` | `user_address` table (keyed `(user_id, merchant_id)`) |\n| `user_wallet_points_balance` | wallet target balance (idempotent via `fn_import_wallet_balance`) |\n| `user_profile_<field_key>` | USER_PROFILE form custom field — **alias kept for backward compatibility** |\n| `form_<form_code>_<field_key>` | Any form whose `form_templates.code = <form_code>`, `status=''published''`, `allow_bulk_import=true` |\n|---|---|---|\n| `user_address_state` | `state` | Province name in TH or EN. Stored verbatim |\n| `user_address_province_code` | `province_code` | 2-digit `address_th_province.id` (e.g. `10` = Bangkok). Wins over name when both supplied |\n| `user_address_district` | `district` | District name in TH or EN. Stored verbatim |\n| `user_address_district_code` | `district_code` | 4-digit `address_th_district.id` (e.g. `1016`). Wins over name when both supplied |\n| `user_address_subdistrict` | `subdistrict` | Subdistrict name in TH or EN. Stored verbatim |\n| `user_address_subdistrict_code` | `subdistrict_code` | 6-digit `address_th_subdistrict.id` (e.g. `101601`). Wins over name when both supplied |\n|---|---|---|\n| `text`, `free_text`, `email`, `phone`, `tel`, `normal`, `number`, `date`, `rating`, `select`, `single_select`, `external_code` | `text_value` | Plain string. Date = `DD-MM-YYYY` |\n| `multi-select` (or any array field) | `array_value` (`text[]`) | Pipe-delimited — `gym\\|yoga\\|running`. If a value contains `\\|`, JSON-encode the whole cell — `[\"a\\|b\",\"c\"]` |\n|---|---|---|\n| `import_mode` | text (`ongoing` \\| `migration`) | Drives `skip_cdc` and `app.skip_side_effects` GUC |\n| `match_on` | text[] | Dedup-key priority order |\n| `field_selection` | jsonb | Snapshot of the chosen field schema for this import (or export) |\n| `chunk_size` | int default 250 | Rows per Inngest chunk call |\n| `last_processed_row_num` | bigint | Resumability cursor into `user_import_staging` |\n| `failed_count` | int | Per-batch failed-row count |\n| `skipped_count` | int | Per-batch skipped-row count |\n| `file_url` | text | Storage URL of the uploaded CSV (for re-download) |\n|---|---|---|\n| `row_num` | bigserial PK | global row number |\n| `batch_id` | uuid FK `bulk_import_batches(id) ON DELETE CASCADE` | |\n| `merchant_id` | uuid FK | RLS isolation |\n| `csv_row_num` | int | 1-based row number from CSV (excluding header rows) |\n| `row_data` | jsonb | The CSV row keyed by machine keys |\n| `row_status` | text | `pending` \\| `valid` \\| `invalid` \\| `processing` \\| `imported` \\| `updated` \\| `skipped` \\| `failed` |\n| `row_errors` | jsonb | Per-row validation/processing errors |\n| `matched_user_id` | uuid | Populated after upsert |\n| `processed_at` | timestamptz | |\n| `created_at` | timestamptz | |\n| Function | Caller | Auth | Purpose |\n|---|---|---|---|\n| `bff_admin_get_importable_fields()` | Admin field picker | `user.read` (implicit via SECURITY DEFINER + RLS) | Returns `{default_fields, address_fields, wallet_fields, forms[]}` for the picker UI. Forms list includes only published forms with `allow_bulk_import=true` (USER_PROFILE always included) |\n| `bff_admin_get_user_import_template_csv(p_field_keys text[])` | Admin \"Download template\" | merchant context | Returns `{csv}` — a CSV string with two-row header (machine keys + labels) for the selected fields |\n| `bff_admin_save_import_schema(p_id, p_name, p_description, p_field_selection)` | Admin save preset | `user.create` | Upsert a saved schema |\n| `bff_admin_list_import_schemas()` | Admin load preset | merchant context | Lists merchant''s schemas |\n| `bff_admin_delete_import_schema(p_id)` | Admin | `user.delete` | Deletes a schema |\n| `bff_admin_start_user_import(p_batch_name, p_file_name, p_import_mode, p_match_on, p_field_selection, p_metadata, p_chunk_size, p_file_url)` | Edge fn `admin-user-import-upload` after parsing CSV | `user.create` | Creates a `bulk_import_batches` row (status `validating`, `import_type=''users''`); returns `batch_id` |\n| `bff_admin_stage_user_import_rows(p_batch_id, p_rows jsonb)` | Edge fn (during CSV streaming) | `user.create` | Inserts rows into `user_import_staging`, runs format validation per row, sets `row_status=''valid''` or `''invalid''` with `row_errors` populated |\n| `bff_admin_run_user_import(p_batch_id)` | FE \"Start import\" CTA | `user.create` | Flips status from `validating` → `pending`. The Inngest worker is event-triggered separately (FE / edge function emits `import/bulk-customers` event with `{batch_id, postprocess_options}`) |\n| `bff_admin_get_user_import_progress(p_batch_id)` | FE poll (every 2s while active) | `user.read` | Returns `{status, total_rows, processed_count, imported_users, failed_count, started_at, completed_at, metadata, error_sample, row_status_counts}` |\n| `bff_admin_list_user_imports(p_limit, p_offset, p_status, p_mode, p_from, p_to)` | FE history page | `user.read` | Paginated `bulk_import_batches WHERE import_type=''users''` |\n| `bff_admin_cancel_user_import(p_batch_id)` | FE cancel | `user.create` | Flips status to `cancelled`; Inngest worker exits at next chunk boundary |\n| `bff_admin_rollback_user_import(p_batch_id)` | FE rollback (migration only) | `user.delete` | Deletes `user_accounts` rows that this batch inserted (cascades clean wallet, form_submissions, etc.). Does NOT undo updates to existing users |\n| `bff_admin_run_user_import_postprocess(p_batch_id, p_options jsonb)` | FE post-migration step | `user.create` | Runs opt-in backfills: `tier_progress`, `fn_auto_assign_on_persona`, mission re-eval enqueue |\n| `bff_admin_start_user_export(p_batch_name, p_field_keys, p_filters)` | FE export wizard | `user.export` | Creates an export batch (`import_type=''users_export''`) for the Inngest worker to stream to Storage |\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/customer-import.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "customer-import", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e345e4cb75089b41e2e459f571ed7a9aedb8fa62781f8d4751a9e03f1f8dbad7", "truncated": true}, "is_active": true}, {"id": "203f0a44-d353-58e2-b3b6-75cdec634516", "feature_slug": "display-settings", "title": "Related functions", "content": "| Function | Purpose |\n|---|---|\n| `fn_build_display_config_with_translations(ds_id, config, merchant_id, default_lang)` | Runs enrichment then overlays per-language translations from the `translations` table (entity_type `display_block_item`) |\n| `fn_extract_display_block_translations(blocks, lang, default_lang)` | Projects a single language out of an all-languages cached payload |\n| `fn_derive_display_block_ui_config(block_type, block_style, config)` | Computed UI hints (e.g. column counts) used by admin and BFF |\n| `fn_transform_images_to_arrays(config)` | Normalises legacy scalar image fields into arrays for admin consumption |\n| `fn_invalidate_display_blocks_cache(merchant_id)` | Drops all cache keys for a merchant. Called automatically by the cache invalidation triggers |\n| `trigger_validate_display_settings_config` | BEFORE INSERT/UPDATE on `display_settings` — enforces the `entity` UUID invariant (SQLSTATE 22P02 on violation) |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Display_Settings.md#L117 Related functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "display-settings", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5e246d79a55cfb79e14ba1a8232f78297982b71a6eef7fd52b350e8be7eb96d7", "truncated": false}, "is_active": true}, {"id": "cbbbd077-ef2e-534f-b4c2-8f48e56af878", "feature_slug": "display-settings", "title": "Tables", "content": "### `display_block_template`\nGlobal catalogue of block shapes. Not per-merchant.\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `block_type` | `display_block_type` enum | `banner`, `banner_hero`, `bottom_menu`, `info_card`, `navigation`, `profile_card`, `announcement`, `featured_rewards`, `points_summary`, `quick_actions`, `tier_progress` |\n| `block_style` | text | e.g. `style_1`, `grid`, `carousel`, `2x2_grid`, `cards`, `horizontal`, `list`, `default` |\n| `config` | jsonb NOT NULL | Canonical empty template — the shape merchants customise |\n\n### `display_settings`\nPer-merchant, per-page placements. Standard columns per `09-db-conventions.mdc` (uuid PK, `merchant_id`, `created_at`, `updated_at`).\n\n| Column | Type | Notes |\n|---|---|---|\n| `block_type` | `display_block_type` | References a template |\n| `block_style` | text | References a template |\n| `page` | `display_page_type` enum | `homepage`, etc. |\n| `order` | integer NOT NULL | Sort key within a page |\n| `active_status` | boolean, default true | Row-level on/off |\n| `persona_ids` | text[] | Empty / NULL = all personas; otherwise includes UUIDs and/or `''guest''` |\n| `config` | jsonb | NULL → fall back to the matching `display_block_template.config` |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Display_Settings.md#L5 Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "display-settings", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4f12f5e640e5e28d8df6ebca23779b658a7e4ec974fc79849f7c21cf3fd878ef", "truncated": false}, "is_active": true}, {"id": "1fd76136-d9be-59c7-87b8-c4eecba9c8f5", "feature_slug": "display-settings", "title": "Read-path RPCs", "content": "All three page-load paths wrap per-block enrichment in an EXCEPTION block. If enrichment throws (should be impossible given the above), the block is returned with raw `config` plus an `enrichment_error` string key — the rest of the page still renders.\n\n| RPC | Caller | Enriches | Cached | Notes |\n|---|---|---|---|---|\n| `api_get_display_blocks_cached(p_page, p_language, p_merchant_code)` | Public FE (merchant_code) | Yes | Yes | Unauth path; persona from `user_accounts` if logged in, else `''guest''` |\n| `bff_get_display_blocks_cached(p_page, p_language)` | Authenticated FE | Yes | Yes | Merchant from `user_accounts` → falls back to `admin_users`; adds `ui_config` |\n| `admin_get_display_blocks(p_page)` | Admin FE | Yes | No | Merges `persona_ids` into `config`, adds `ui_config`; returns both active and inactive blocks |\n| `bff_get_display_settings(p_page, p_language_code)` | Authenticated FE | No (raw config) | No | Returns raw rows plus per-row translations object |\n\nCache key: `merchant:<uuid>:display_blocks:<page>:persona:<persona_id_or_guest>:all_languages`. TTL 300s. Invalidated by `trg_invalidate_display_blocks_cache_on_settings` (AFTER INSERT/UPDATE/DELETE on `display_settings`) and `trg_invalidate_display_blocks_cache_on_translation_change` (translations).", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Display_Settings.md#L77 Read-path RPCs", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "display-settings", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2399c77b08dcac3e7c2e91f1647c69af9d9fdf49061fd47bf27cdc61f4bf08ee", "truncated": false}, "is_active": true}, {"id": "cd4a4446-cef2-5fcf-819a-b3fd32499b91", "feature_slug": "display-settings", "title": "Display Settings Domain Reference", "content": "**Keywords:** display_settings, display_block_template, display_blocks, homepage, block_type, block_style, profile_card, banner, banner_hero, navigation, bottom_menu, announcement, group_1, group_2, object (group), entity (item), persona_ids, enrichment, display_page_type, display_block_type, merchant_widget_settings, widget_config_template, widget_type, shopify_widget\n**Source:** `Display_Settings.md`\n**Tables:**\n| Function | Type | Purpose |\n|---|---|---|\n| `api_get_display_blocks_cached(p_page, p_language, p_merchant_code)` | API | Public FE page load (merchant_code param); cached, fail-soft per block |\n| `bff_get_display_blocks_cached(p_page, p_language)` | BFF | Authenticated FE page load; cached, includes `ui_config`, fail-soft per block |\n| `admin_get_display_blocks(p_page)` | BFF | Admin editor list — active + inactive, with `persona_ids` merged and `ui_config`, fail-soft per block |\n| `bff_get_display_settings(p_page, p_language_code)` | BFF | Raw rows + translations; does not enrich |\n| `fn_enrich_display_config(p_config)` | Backend | Entity lookups for `group_*.items[*].entity`; skips inactive groups; skips non-UUID entity with `RAISE NOTICE` (never raises) |\n| `fn_build_display_config_with_translations(...)` | Backend | Enrichment + per-language translation overlay |\n| `fn_derive_display_block_ui_config(...)` | Backend | Computed UI hints |\n| `fn_transform_images_to_arrays(...)` | Backend | Legacy scalar→array image normalisation |\n| `fn_invalidate_display_blocks_cache(p_merchant_id)` | Backend | Purge all cache keys for a merchant |\n| `get_display_settings_menu()` | Backend | Catalogue of templates + styles for the admin editor |\n| `get_entity_options_by_type(p_entity_type)` | Backend | `{id, name}[]` picker source. Accepts `reward`, `mission`, `tier`, `persona`, `product_*`, `store`, `store_attribute_set` |\n| `trigger_validate_display_settings_config` | Trigger | BEFORE INSERT/UPDATE on `display_settings`; rejects non-UUID `entity` with SQLSTATE 22P02 naming the offending path |\n**Key Business Rules:**\n- `config.group_*.items[*].entity` must be \"\" or a UUID. Labels like `\"reward\"` are rejected by trigger.\n- `object` on a group is one of `rewards | missions | tiers | personas` (or \"\"); only these produce entity enrichment.\n- `active: false` on a group short-circuits enrichment for that group.\n- Row-level `active_status = false` hides a block from the user-facing RPCs but not the admin RPC.\n- `persona_ids` is a `text[]` accepting UUIDs and/or the literal string `''guest''` for unauthenticated viewers; empty/NULL means all personas.\n- Cache key includes `merchant_id`, page, persona, and all-languages; TTL 300s; invalidated by AFTER triggers on `display_settings` and `translations`.\n\n|---|---|---|\n| `merchant_widget_settings` | `(id uuid, merchant_id uuid FK→merchant_master, widget_type text, config jsonb, active_status bool, created_at, updated_at)` | UNIQUE `(merchant_id, widget_type)` — one row per surface per merchant. RLS: isolation by `request.jwt.claims.merchant_id` + permissive `SELECT` for anon (storefront via `api_*`). |\n| `widget_config_template` | `(id uuid, widget_type text UNIQUE, config_default jsonb, schema_version text, storage_bucket text, storage_path_template text, created_at, updated_at)` | Catalogue of widget surfaces. Seeded with `widget_type=''shopify''`, `storage_bucket=''images''` (same as main display settings), `storage_path_template=''widget/{merchant_id}/''`. RLS: permissive read. |\n| Function | Type | Purpose |\n|---|---|---|\n| `get_widget_settings_menu()` | Backend | Catalogue of available widget surfaces with per-widget `storage` hint — feeds admin surface picker. Mirrors `get_display_settings_menu`. |\n| `fn_resolve_widget_storage(p_widget_type, p_merchant_id)` | Backend | Returns resolved storage upload target `{bucket, path_prefix, public, max_file_size_kb, allowed_mime_types}` for FE upload widgets. Substitutes `{merchant_id}`, `{merchant_code}`, `{widget_type}` tokens. |\n| `admin_get_widget_settings(p_widget_type)` | BFF | Admin editor load: returns merchant row (or template default if none) + `resolved` block (primary_color + points display) from `merchant_display_settings` + resolved `storage` target. |\n| `admin_upsert_widget_settings(p_widget_type, p_config, p_active_status)` | BFF | In-place upsert keyed on `(merchant_id, widget_type)`. Pre-validates via `fn_validate_widget_config` — returns structured error array on failure. |\n| `admin_reset_widget_settings(p_widget_type)` | BFF | Resets row to `widget_config_template.config_default`. |\n| `admin_upsert_merchant_points_display(p_label, p_symbol_type, p_symbol_icon, p_symbol_image_url)` | BFF | Targeted write for `merchant_display_settings.points_unit_label`/`points_symbol_*`. Validates icon list (12 keys) + cross-field rule (image type requires non-empty url). Single source of truth for the merchant''s points unit name + symbol used by widget, LIFF, admin views. |\n| `bff_get_widget_settings(p_widget_type)` | BFF | Authenticated read. Cached 300s in `extensions.ui_cache`. Resolves primary_color, points display, and storage target. No language param. |\n| `api_get_widget_settings_cached(p_widget_type, p_merchant_code)` | API | Anon storefront read for widget JS. Cached 300s. Fail-soft — returns template defaults on any error. No language param. |\n| `fn_validate_widget_config(p_widget_type, p_config)` | Backend | Returns `{ok bool, errors[]:{path,code,message}}`. Used by trigger and admin pre-save. Rejects deprecated `point` block. |\n| `fn_widget_config_with_defaults(p_widget_type, p_config)` | Backend | Shallow-merges saved config over `config_default`. |\n| `fn_resolve_widget_merchant_display(p_merchant_id)` | Backend | Returns `{primary_color, points:{unit_label, symbol_type, symbol_icon, symbol_image_url}}` from `merchant_display_settings`. Single helper used by all 3 widget read RPCs to keep the `resolved` block consistent. |\n| `fn_invalidate_widget_settings_cache(p_merchant_id, p_widget_type)` | Backend | Purges `merchant:{id}:widget:{type}` cache key via `extensions.ui_cache_del`. |\n| `trigger_validate_widget_settings_config` | Trigger | BEFORE INSERT/UPDATE on `merchant_widget_settings`; raises SQLSTATE 22P02 with offending JSON path on validation failure. |\n| `trigger_invalidate_widget_settings_cache_on_change` | Trigger | AFTER INSERT/UPDATE/DELETE on `merchant_widget_settings`. |\n| `trigger_invalidate_widget_cache_on_merchant_display_change` | Trigger | AFTER INSERT/UPDATE/DELETE on `merchant_display_settings`. Purges all widget cache keys for that merchant — ensures `primary_color` and `points_*` changes propagate within seconds. |", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/display-settings.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "display-settings", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c308fab095be4ad38b1517d42eaee634dc1aba6f1a8aa7f70b40e2ca53b704ac", "truncated": false}, "is_active": true}, {"id": "56371cae-7442-5e5f-87f7-1094e48126a9", "feature_slug": "event-order-consumers", "title": "Overview", "content": "Two consumers in `crm-event-processors` need additive changes to support:\n1. **CurrencyConsumer** — award currency on pending event orders (existing completed flow unchanged)\n2. **AmpConsumer** — trigger AMP workflows on pending event orders (for reward push)\n\nBoth changes are **additive only** — existing routing logic is not modified.\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/Event_Order_Consumer_Changes.md#L3 Overview", "metadata": {"source_doc_type": "implementation_note", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "event-order-consumers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5f0fa6f0314ff9c441d418b114325fcfe41d683e9ca32da37ed73464bd29ebd1", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
